BEGIN;
DO $$
DECLARE
  v_subject_id UUID;
  v_topic_id UUID;
  v_test_id BIGINT;
BEGIN
  SELECT id INTO v_subject_id FROM test_subjects WHERE name ILIKE '%cardio%' ORDER BY id LIMIT 1;
  IF v_subject_id IS NULL THEN
    INSERT INTO test_subjects (name, description) VALUES ('Cardiovascular System', 'Cardiovascular notes') RETURNING id INTO v_subject_id;
  END IF;
  SELECT id INTO v_topic_id FROM test_topics WHERE name = 'Hypertension, Hypotension, CO & SV' ORDER BY (SELECT COUNT(*) FROM test_questions q WHERE q.topic_id = test_topics.id) DESC, created_at ASC LIMIT 1;
  IF v_topic_id IS NULL THEN
    INSERT INTO test_topics (subject_id, name, description, status) VALUES (v_subject_id, 'Hypertension, Hypotension, CO & SV', 'Blood pressure physiology and management', 'published') RETURNING id INTO v_topic_id;
  END IF;
  SELECT id INTO v_test_id FROM tests WHERE is_active = true ORDER BY id LIMIT 1;
  IF v_test_id IS NULL THEN
    INSERT INTO tests (test_name, system_category, description, is_active)
    VALUES ('Cardiovascular System - HTN/Hypotension/CO/SV (Generated)', 'Cardiovascular System', 'Auto-generated NCLEX question set', true)
    RETURNING id INTO v_test_id;
  END IF;
  DELETE FROM test_questions WHERE topic_id = v_topic_id AND category = 'Hypertension Hypotension CO SV - NCLEX';
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Hypertension, Hypotension, CO & SV note, which statement about "BP formula" is most accurate?', 'According to the Hypertension, Hypotension, CO & SV note, which statement about "BP formula" is most accurate?', '[{"id": "a", "text": "SVR is defined as oxygen saturation."}, {"id": "b", "text": "SVR has no influence on BP."}, {"id": "c", "text": "Afterload means venous return volume."}, {"id": "d", "text": "Falling CO can lower BP if SVR unchanged."}]'::jsonb, '["d"]'::jsonb, 'Correct because Blood pressure is determined by cardiac output multiplied by systemic vascular resistance (BP = CO × SVR). Interpret BP changes by evaluating both pump flow and vascular tone.', 'Hypertension Hypotension CO SV - NCLEX', false, 1, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "CO formula" in Hypertension, Hypotension, CO & SV. Which statement is correct?', 'The nurse is reviewing "CO formula" in Hypertension, Hypotension, CO & SV. Which statement is correct?', '[{"id": "a", "text": "High-salt diet is recommended for HTN."}, {"id": "b", "text": "Formula is explicitly provided in note."}, {"id": "c", "text": "CO equals MAP divided by pulse pressure."}, {"id": "d", "text": "Sedentary rest is first-line lifestyle."}]'::jsonb, '["b"]'::jsonb, 'Correct because Cardiac output equals stroke volume times heart rate (CO = SV × HR). Assess tachy/bradycardia and stroke volume drivers when perfusion worsens.', 'Hypertension Hypotension CO SV - NCLEX', false, 2, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "MAP formula and normal" in Hypertension, Hypotension, CO & SV?', 'Which clinical judgment is most accurate regarding "MAP formula and normal" in Hypertension, Hypotension, CO & SV?', '[{"id": "a", "text": "MAP formula weights diastolic pressure twice."}, {"id": "b", "text": "ACE inhibitors have no cough risk."}, {"id": "c", "text": "MAP is calculated as SBP + DBP divided by 2."}, {"id": "d", "text": "ACE inhibitors are preferred during pregnancy."}]'::jsonb, '["a"]'::jsonb, 'Correct because MAP is calculated as (2×DBP + SBP) ÷ 3 and normal range listed is 70–100 mmHg. Use MAP for organ perfusion triage, not SBP alone.', 'Hypertension Hypotension CO SV - NCLEX', false, 3, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Core definitions" in Hypertension, Hypotension, CO & SV?', 'In rapid prioritization, which statement is most consistent with "Core definitions" in Hypertension, Hypotension, CO & SV?', '[{"id": "a", "text": "ARBs are only emergency IV drugs."}, {"id": "b", "text": "SVR is defined as oxygen saturation."}, {"id": "c", "text": "Afterload means venous return volume."}, {"id": "d", "text": "Afterload is resistance to ejection."}]'::jsonb, '["d"]'::jsonb, 'Correct because BP is force against artery walls, CO is blood pumped per minute by LV, SV is blood per beat, SVR is resistance to LV ejection, preload is venous return stretch, afterload is resistance to ejection. Distinguish preload/afterload effects when choosing interventions.', 'Hypertension Hypotension CO SV - NCLEX', false, 4, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "HTN staging normal/elevated" in Hypertension, Hypotension, CO & SV would the nurse recognize as correct?', 'Which conclusion about "HTN staging normal/elevated" in Hypertension, Hypotension, CO & SV would the nurse recognize as correct?', '[{"id": "a", "text": "Elevated has SBP 120–129 with DBP <80."}, {"id": "b", "text": "Normal BP is listed as under 140/90."}, {"id": "c", "text": "Beta-blockers increase contractility."}, {"id": "d", "text": "CCBs are listed as preload boosters."}]'::jsonb, '["a"]'::jsonb, 'Correct because Normal BP is <120/<80 and elevated is 120–129 systolic with diastolic <80. Catch early elevation stage to prevent progression.', 'Hypertension Hypotension CO SV - NCLEX', false, 5, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Hypertension, Hypotension, CO & SV note, which statement about "HTN stages 1 and 2" is most accurate?', 'According to the Hypertension, Hypotension, CO & SV note, which statement about "HTN stages 1 and 2" is most accurate?', '[{"id": "a", "text": "Stage 1 starts at SBP 150."}, {"id": "b", "text": "Oral-only delayed treatment is recommended."}, {"id": "c", "text": "Aggressive BP shifts are always preferred regardless of organ perfusion."}, {"id": "d", "text": "Stage 1 HTN is 130–139 or 80–89; stage 2 is ≥140 or ≥90."}]'::jsonb, '["d"]'::jsonb, 'Correct because Stage 1 HTN is 130–139 or 80–89; stage 2 is ≥140 or ≥90. Stage classification guides urgency and treatment intensity.', 'Hypertension Hypotension CO SV - NCLEX', false, 6, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Hypertensive crisis threshold" in Hypertension, Hypotension, CO & SV. Which statement is correct?', 'The nurse is reviewing "Hypertensive crisis threshold" in Hypertension, Hypotension, CO & SV. Which statement is correct?', '[{"id": "a", "text": "ACE inhibitors are preferred during pregnancy."}, {"id": "b", "text": "MAP has no role in emergency treatment."}, {"id": "c", "text": "Crisis starts at 150/90."}, {"id": "d", "text": "Crisis threshold includes diastolic above 120."}]'::jsonb, '["d"]'::jsonb, 'Correct because Hypertensive crisis is listed as BP >180/>120. Escalate rapidly and assess for acute organ damage.', 'Hypertension Hypotension CO SV - NCLEX', false, 7, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "HTN risk factors" in Hypertension, Hypotension, CO & SV?', 'Which clinical judgment is most accurate regarding "HTN risk factors" in Hypertension, Hypotension, CO & SV?', '[{"id": "a", "text": "Stress has no relation to HTN."}, {"id": "b", "text": "Any low BP without symptoms is always shock."}, {"id": "c", "text": "Smoking and obesity are modifiable risks."}, {"id": "d", "text": "Hypotension is defined as SBP under 130."}]'::jsonb, '["c"]'::jsonb, 'Correct because Non-modifiable risks include age, family history, and race; modifiable include obesity, smoking, high sodium diet, sedentary lifestyle, alcohol, and stress. Target modifiable risks aggressively for BP control.', 'Hypertension Hypotension CO SV - NCLEX', false, 8, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "HTN complications" in Hypertension, Hypotension, CO & SV?', 'In rapid prioritization, which statement is most consistent with "HTN complications" in Hypertension, Hypotension, CO & SV?', '[{"id": "a", "text": "Uncontrolled BP requires organ-protection strategy and close follow-up."}, {"id": "b", "text": "Because perfusion appears stable, immediate reassessment is unnecessary."}, {"id": "c", "text": "Aggressive BP shifts are always preferred regardless of organ perfusion."}, {"id": "d", "text": "HTN has no end-organ complications."}]'::jsonb, '["a"]'::jsonb, 'Correct because Complications listed are stroke, MI, heart failure, CKD, and retinal damage. Uncontrolled BP requires organ-protection strategy and close follow-up.', 'Hypertension Hypotension CO SV - NCLEX', false, 9, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Lifestyle HTN management" in Hypertension, Hypotension, CO & SV would the nurse recognize as correct?', 'Which conclusion about "Lifestyle HTN management" in Hypertension, Hypotension, CO & SV would the nurse recognize as correct?', '[{"id": "a", "text": "Exercise and weight loss are recommended."}, {"id": "b", "text": "Oral-only delayed treatment is recommended."}, {"id": "c", "text": "Orthostatic criteria require HR rise only."}, {"id": "d", "text": "Sedentary rest is first-line lifestyle."}]'::jsonb, '["a"]'::jsonb, 'Correct because Lifestyle management includes DASH (lower sodium/higher potassium), exercise, weight loss, and smoking cessation. Pair medication with sustained lifestyle adherence for long-term control.', 'Hypertension Hypotension CO SV - NCLEX', false, 10, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Hypertension, Hypotension, CO & SV note, which statement about "ACE inhibitor specifics" is most accurate?', 'According to the Hypertension, Hypotension, CO & SV note, which statement about "ACE inhibitor specifics" is most accurate?', '[{"id": "a", "text": "ACE inhibitors are preferred during pregnancy."}, {"id": "b", "text": "ACE inhibitors are contraindicated in pregnancy."}, {"id": "c", "text": "Hydration should be restricted in orthostasis."}, {"id": "d", "text": "Oral-only delayed treatment is recommended."}]'::jsonb, '["b"]'::jsonb, 'Correct because ACE inhibitors (e.g., lisinopril) can cause dry cough and are contraindicated in pregnancy. Screen for pregnancy status and cough intolerance.', 'Hypertension Hypotension CO SV - NCLEX', false, 11, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "ARB specifics" in Hypertension, Hypotension, CO & SV. Which statement is correct?', 'The nurse is reviewing "ARB specifics" in Hypertension, Hypotension, CO & SV. Which statement is correct?', '[{"id": "a", "text": "ARBs are only emergency IV drugs."}, {"id": "b", "text": "ARBs are used when ACE not tolerated."}, {"id": "c", "text": "MAP has no role in emergency treatment."}, {"id": "d", "text": "Hypotension is defined as SBP under 130."}]'::jsonb, '["b"]'::jsonb, 'Correct because ARBs (e.g., losartan) are used if ACE inhibitors are not tolerated and do not cause cough per note. Use ARB substitution when ACE cough limits adherence.', 'Hypertension Hypotension CO SV - NCLEX', false, 12, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Thiazide/CCB/beta-blocker roles" in Hypertension, Hypotension, CO & SV?', 'Which clinical judgment is most accurate regarding "Thiazide/CCB/beta-blocker roles" in Hypertension, Hypotension, CO & SV?', '[{"id": "a", "text": "Beta-blockers increase contractility."}, {"id": "b", "text": "Metoprolol lowers HR and contractility."}, {"id": "c", "text": "CCBs are listed as preload boosters."}, {"id": "d", "text": "Hypotension is defined as SBP under 130."}]'::jsonb, '["b"]'::jsonb, 'Correct because Thiazides are first-line for most patients, CCBs cause vasodilation, and beta-blockers reduce HR/contractility. Match medication mechanism to hemodynamic target.', 'Hypertension Hypotension CO SV - NCLEX', false, 13, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Hypertensive emergency treatment" in Hypertension, Hypotension, CO & SV?', 'In rapid prioritization, which statement is most consistent with "Hypertensive emergency treatment" in Hypertension, Hypotension, CO & SV?', '[{"id": "a", "text": "Orthostatic criteria require HR rise only."}, {"id": "b", "text": "HR has no relation to CO in this table."}, {"id": "c", "text": "Organ damage presence defines emergency context."}, {"id": "d", "text": "Oral-only delayed treatment is recommended."}]'::jsonb, '["c"]'::jsonb, 'Correct because Hypertensive emergency with organ damage requires IV antihypertensives such as nicardipine, labetalol, or nitroprusside. Treat with controlled IV reduction while monitoring perfusion.', 'Hypertension Hypotension CO SV - NCLEX', false, 14, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "MAP reduction limit" in Hypertension, Hypotension, CO & SV would the nurse recognize as correct?', 'Which conclusion about "MAP reduction limit" in Hypertension, Hypotension, CO & SV would the nurse recognize as correct?', '[{"id": "a", "text": "Preload is unaffected by fluid status."}, {"id": "b", "text": "Drop must occur after 30 minutes."}, {"id": "c", "text": "First-hour MAP reduction cap is 25%."}, {"id": "d", "text": "MAP has no role in emergency treatment."}]'::jsonb, '["c"]'::jsonb, 'Correct because In hypertensive emergency, MAP should not be reduced by more than 25% in the first hour. Avoid overcorrection that can cause organ hypoperfusion.', 'Hypertension Hypotension CO SV - NCLEX', false, 15, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Hypertension, Hypotension, CO & SV note, which statement about "Hypotension definition" is most accurate?', 'According to the Hypertension, Hypotension, CO & SV note, which statement about "Hypotension definition" is most accurate?', '[{"id": "a", "text": "Warm flushed skin with high urine output is hallmark."}, {"id": "b", "text": "Any low BP without symptoms is always shock."}, {"id": "c", "text": "Hydration should be restricted in orthostasis."}, {"id": "d", "text": "Clinical significance depends on perfusion impact."}]'::jsonb, '["d"]'::jsonb, 'Correct because Hypotension is systolic <90 or diastolic <60 and is significant when symptoms or hypoperfusion are present. Treat symptomatic low BP rapidly to protect organ perfusion.', 'Hypertension Hypotension CO SV - NCLEX', false, 16, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Hypotension types and causes" in Hypertension, Hypotension, CO & SV. Which statement is correct?', 'The nurse is reviewing "Hypotension types and causes" in Hypertension, Hypotension, CO & SV. Which statement is correct?', '[{"id": "a", "text": "Identify subtype/cause to guide targeted therapy."}, {"id": "b", "text": "Only neurogenic hypotension exists."}, {"id": "c", "text": "Diuresis is first-line for hypovolemic hypotension."}, {"id": "d", "text": "Warm flushed skin with high urine output is hallmark."}]'::jsonb, '["a"]'::jsonb, 'Correct because Types listed are orthostatic, hypovolemic, neurogenic, and cardiogenic; causes include bleeding/dehydration, HF, sepsis, medications, and Addison disease. Identify subtype/cause to guide targeted therapy.', 'Hypertension Hypotension CO SV - NCLEX', false, 17, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Orthostatic criteria" in Hypertension, Hypotension, CO & SV?', 'Which clinical judgment is most accurate regarding "Orthostatic criteria" in Hypertension, Hypotension, CO & SV?', '[{"id": "a", "text": "HR has no relation to CO in this table."}, {"id": "b", "text": "Diuresis is first-line for hypovolemic hypotension."}, {"id": "c", "text": "Timing window is within 3 minutes of standing."}, {"id": "d", "text": "Orthostatic criteria require HR rise only."}]'::jsonb, '["c"]'::jsonb, 'Correct because Orthostatic hypotension is drop ≥20 systolic or ≥10 diastolic within 3 minutes of standing. Measure postural vitals correctly before labeling orthostasis.', 'Hypertension Hypotension CO SV - NCLEX', false, 18, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Orthostatic management" in Hypertension, Hypotension, CO & SV?', 'In rapid prioritization, which statement is most consistent with "Orthostatic management" in Hypertension, Hypotension, CO & SV?', '[{"id": "a", "text": "Hydration should be restricted in orthostasis."}, {"id": "b", "text": "CO equals MAP divided by pulse pressure."}, {"id": "c", "text": "HR has no relation to CO in this table."}, {"id": "d", "text": "Slow position changes are recommended."}]'::jsonb, '["d"]'::jsonb, 'Correct because Nursing actions include dangling legs before standing, slow position changes, and adequate hydration. Prevent falls and syncope with positional safety teaching.', 'Hypertension Hypotension CO SV - NCLEX', false, 19, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Hypotension symptoms" in Hypertension, Hypotension, CO & SV would the nurse recognize as correct?', 'Which conclusion about "Hypotension symptoms" in Hypertension, Hypotension, CO & SV would the nurse recognize as correct?', '[{"id": "a", "text": "Warm flushed skin with high urine output is hallmark."}, {"id": "b", "text": "Aggressive BP shifts are always preferred regardless of organ perfusion."}, {"id": "c", "text": "Because perfusion appears stable, immediate reassessment is unnecessary."}, {"id": "d", "text": "Trend neuro, skin, pulse, and urine output for perfusion decline."}]'::jsonb, '["d"]'::jsonb, 'Correct because Symptoms include dizziness, syncope, blurred vision, confusion, compensatory tachycardia, cool pale skin, and low urine output. Trend neuro, skin, pulse, and urine output for perfusion decline.', 'Hypertension Hypotension CO SV - NCLEX', false, 20, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Hypertension, Hypotension, CO & SV note, which statement about "Hypotension treatment" is most accurate?', 'According to the Hypertension, Hypotension, CO & SV note, which statement about "Hypotension treatment" is most accurate?', '[{"id": "a", "text": "IV fluids/blood products used if hypovolemic."}, {"id": "b", "text": "Vasoconstriction always increases CO."}, {"id": "c", "text": "Diuresis is first-line for hypovolemic hypotension."}, {"id": "d", "text": "Afterload means venous return volume."}]'::jsonb, '["a"]'::jsonb, 'Correct because Management includes treating cause, IV fluids or blood products for hypovolemia, vasopressors for severe cases, supine position with legs elevated, and slow postural changes. Restore circulating volume and perfusion while preventing recurrent drops.', 'Hypertension Hypotension CO SV - NCLEX', false, 21, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "CO factors: heart rate" in Hypertension, Hypotension, CO & SV. Which statement is correct?', 'The nurse is reviewing "CO factors: heart rate" in Hypertension, Hypotension, CO & SV. Which statement is correct?', '[{"id": "a", "text": "Normal BP is listed as under 140/90."}, {"id": "b", "text": "Tachycardia and epinephrine can raise CO in table."}, {"id": "c", "text": "HR has no relation to CO in this table."}, {"id": "d", "text": "MAP 55 is acceptable organ perfusion."}]'::jsonb, '["b"]'::jsonb, 'Correct because CO can increase with tachycardia/epinephrine and decrease with bradycardia/beta-blockers per table. Evaluate whether HR changes are compensatory or harmful to perfusion.', 'Hypertension Hypotension CO SV - NCLEX', false, 22, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "CO factors: preload" in Hypertension, Hypotension, CO & SV?', 'Which clinical judgment is most accurate regarding "CO factors: preload" in Hypertension, Hypotension, CO & SV?', '[{"id": "a", "text": "Preload is unaffected by fluid status."}, {"id": "b", "text": "SVR has no influence on BP."}, {"id": "c", "text": "CO equals MAP divided by pulse pressure."}, {"id": "d", "text": "Higher fluid volume can increase preload/CO."}]'::jsonb, '["d"]'::jsonb, 'Correct because Preload increase with fluid volume can raise CO; dehydration/hemorrhage lower preload and CO. Volume assessment is central in hypotension and shock states.', 'Hypertension Hypotension CO SV - NCLEX', false, 23, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "CO factors: afterload/contractility" in Hypertension, Hypotension, CO & SV?', 'In rapid prioritization, which statement is most consistent with "CO factors: afterload/contractility" in Hypertension, Hypotension, CO & SV?', '[{"id": "a", "text": "MAP is calculated as SBP + DBP divided by 2."}, {"id": "b", "text": "Higher SVR can reduce CO in the table context."}, {"id": "c", "text": "CO equals MAP divided by pulse pressure."}, {"id": "d", "text": "Vasoconstriction always increases CO."}]'::jsonb, '["b"]'::jsonb, 'Correct because Vasodilation (lower SVR) can improve CO while vasoconstriction (higher SVR) can reduce CO; contractility rises with digoxin/epinephrine and falls with HF/MI. Balance vascular tone and contractility when optimizing output.', 'Hypertension Hypotension CO SV - NCLEX', false, 24, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "NCLEX MAP warning" in Hypertension, Hypotension, CO & SV would the nurse recognize as correct?', 'Which conclusion about "NCLEX MAP warning" in Hypertension, Hypotension, CO & SV would the nurse recognize as correct?', '[{"id": "a", "text": "Afterload means venous return volume."}, {"id": "b", "text": "MAP <60 is ischemia risk in note tip."}, {"id": "c", "text": "MAP 55 is acceptable organ perfusion."}, {"id": "d", "text": "No action needed unless MAP <20."}]'::jsonb, '["b"]'::jsonb, 'Correct because MAP below 60 mmHg means organs are at risk of ischemia and immediate BP/oxygenation support is priority. Treat MAP <60 as urgent perfusion threat.', 'Hypertension Hypotension CO SV - NCLEX', false, 25, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Hypertension, Hypotension, CO & SV note, which statement about "BP formula" is most accurate?', 'According to the Hypertension, Hypotension, CO & SV note, which statement about "BP formula" is most accurate?', '[{"id": "a", "text": "Rising SVR can increase BP when CO constant."}, {"id": "b", "text": "SVR is defined as oxygen saturation."}, {"id": "c", "text": "SVR has no influence on BP."}, {"id": "d", "text": "Afterload means venous return volume."}]'::jsonb, '["a"]'::jsonb, 'Correct because Blood pressure is determined by cardiac output multiplied by systemic vascular resistance (BP = CO × SVR). Interpret BP changes by evaluating both pump flow and vascular tone.', 'Hypertension Hypotension CO SV - NCLEX', false, 26, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "CO formula" in Hypertension, Hypotension, CO & SV. Which statement is correct?', 'The nurse is reviewing "CO formula" in Hypertension, Hypotension, CO & SV. Which statement is correct?', '[{"id": "a", "text": "CO equals MAP divided by pulse pressure."}, {"id": "b", "text": "Normal BP is listed as under 140/90."}, {"id": "c", "text": "High-salt diet is recommended for HTN."}, {"id": "d", "text": "Changes in either HR or SV change CO."}]'::jsonb, '["d"]'::jsonb, 'Correct because Cardiac output equals stroke volume times heart rate (CO = SV × HR). Assess tachy/bradycardia and stroke volume drivers when perfusion worsens.', 'Hypertension Hypotension CO SV - NCLEX', false, 27, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "MAP formula and normal" in Hypertension, Hypotension, CO & SV?', 'Which clinical judgment is most accurate regarding "MAP formula and normal" in Hypertension, Hypotension, CO & SV?', '[{"id": "a", "text": "ACE inhibitors are preferred during pregnancy."}, {"id": "b", "text": "MAP interpretation is key for perfusion."}, {"id": "c", "text": "MAP is calculated as SBP + DBP divided by 2."}, {"id": "d", "text": "ACE inhibitors have no cough risk."}]'::jsonb, '["b"]'::jsonb, 'Correct because MAP is calculated as (2×DBP + SBP) ÷ 3 and normal range listed is 70–100 mmHg. Use MAP for organ perfusion triage, not SBP alone.', 'Hypertension Hypotension CO SV - NCLEX', false, 28, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Core definitions" in Hypertension, Hypotension, CO & SV?', 'In rapid prioritization, which statement is most consistent with "Core definitions" in Hypertension, Hypotension, CO & SV?', '[{"id": "a", "text": "Afterload means venous return volume."}, {"id": "b", "text": "ARBs are only emergency IV drugs."}, {"id": "c", "text": "SVR is defined as oxygen saturation."}, {"id": "d", "text": "SV is blood volume pumped per beat."}]'::jsonb, '["d"]'::jsonb, 'Correct because BP is force against artery walls, CO is blood pumped per minute by LV, SV is blood per beat, SVR is resistance to LV ejection, preload is venous return stretch, afterload is resistance to ejection. Distinguish preload/afterload effects when choosing interventions.', 'Hypertension Hypotension CO SV - NCLEX', false, 29, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "HTN staging normal/elevated" in Hypertension, Hypotension, CO & SV would the nurse recognize as correct?', 'Which conclusion about "HTN staging normal/elevated" in Hypertension, Hypotension, CO & SV would the nurse recognize as correct?', '[{"id": "a", "text": "CCBs are listed as preload boosters."}, {"id": "b", "text": "Catch early elevation stage to prevent progression."}, {"id": "c", "text": "Normal BP is listed as under 140/90."}, {"id": "d", "text": "Beta-blockers increase contractility."}]'::jsonb, '["b"]'::jsonb, 'Correct because Normal BP is <120/<80 and elevated is 120–129 systolic with diastolic <80. Catch early elevation stage to prevent progression.', 'Hypertension Hypotension CO SV - NCLEX', false, 30, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Hypertension, Hypotension, CO & SV note, which statement about "HTN stages 1 and 2" is most accurate?', 'According to the Hypertension, Hypotension, CO & SV note, which statement about "HTN stages 1 and 2" is most accurate?', '[{"id": "a", "text": "Aggressive BP shifts are always preferred regardless of organ perfusion."}, {"id": "b", "text": "Because perfusion appears stable, immediate reassessment is unnecessary."}, {"id": "c", "text": "Stage classification guides urgency and treatment intensity."}, {"id": "d", "text": "Stage 1 starts at SBP 150."}]'::jsonb, '["c"]'::jsonb, 'Correct because Stage 1 HTN is 130–139 or 80–89; stage 2 is ≥140 or ≥90. Stage classification guides urgency and treatment intensity.', 'Hypertension Hypotension CO SV - NCLEX', false, 31, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Hypertensive crisis threshold" in Hypertension, Hypotension, CO & SV. Which statement is correct?', 'The nurse is reviewing "Hypertensive crisis threshold" in Hypertension, Hypotension, CO & SV. Which statement is correct?', '[{"id": "a", "text": "Crisis starts at 150/90."}, {"id": "b", "text": "Sedentary rest is first-line lifestyle."}, {"id": "c", "text": "Crisis threshold includes systolic above 180."}, {"id": "d", "text": "MAP has no role in emergency treatment."}]'::jsonb, '["c"]'::jsonb, 'Correct because Hypertensive crisis is listed as BP >180/>120. Escalate rapidly and assess for acute organ damage.', 'Hypertension Hypotension CO SV - NCLEX', false, 32, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "HTN risk factors" in Hypertension, Hypotension, CO & SV?', 'Which clinical judgment is most accurate regarding "HTN risk factors" in Hypertension, Hypotension, CO & SV?', '[{"id": "a", "text": "Any low BP without symptoms is always shock."}, {"id": "b", "text": "Target modifiable risks aggressively for BP control."}, {"id": "c", "text": "ACE inhibitors are preferred during pregnancy."}, {"id": "d", "text": "Stress has no relation to HTN."}]'::jsonb, '["b"]'::jsonb, 'Correct because Non-modifiable risks include age, family history, and race; modifiable include obesity, smoking, high sodium diet, sedentary lifestyle, alcohol, and stress. Target modifiable risks aggressively for BP control.', 'Hypertension Hypotension CO SV - NCLEX', false, 33, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "HTN complications" in Hypertension, Hypotension, CO & SV?', 'In rapid prioritization, which statement is most consistent with "HTN complications" in Hypertension, Hypotension, CO & SV?', '[{"id": "a", "text": "Aggressive BP shifts are always preferred regardless of organ perfusion."}, {"id": "b", "text": "HTN has no end-organ complications."}, {"id": "c", "text": "Because perfusion appears stable, immediate reassessment is unnecessary."}, {"id": "d", "text": "Uncontrolled BP requires organ-protection strategy and close follow-up."}]'::jsonb, '["d"]'::jsonb, 'Correct because Complications listed are stroke, MI, heart failure, CKD, and retinal damage. Uncontrolled BP requires organ-protection strategy and close follow-up.', 'Hypertension Hypotension CO SV - NCLEX', false, 34, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Lifestyle HTN management" in Hypertension, Hypotension, CO & SV would the nurse recognize as correct?', 'Which conclusion about "Lifestyle HTN management" in Hypertension, Hypotension, CO & SV would the nurse recognize as correct?', '[{"id": "a", "text": "Pair medication with sustained lifestyle adherence for long-term control."}, {"id": "b", "text": "Aggressive BP shifts are always preferred regardless of organ perfusion."}, {"id": "c", "text": "Because perfusion appears stable, immediate reassessment is unnecessary."}, {"id": "d", "text": "Sedentary rest is first-line lifestyle."}]'::jsonb, '["a"]'::jsonb, 'Correct because Lifestyle management includes DASH (lower sodium/higher potassium), exercise, weight loss, and smoking cessation. Pair medication with sustained lifestyle adherence for long-term control.', 'Hypertension Hypotension CO SV - NCLEX', false, 35, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Hypertension, Hypotension, CO & SV note, which statement about "ACE inhibitor specifics" is most accurate?', 'According to the Hypertension, Hypotension, CO & SV note, which statement about "ACE inhibitor specifics" is most accurate?', '[{"id": "a", "text": "Screen for pregnancy status and cough intolerance."}, {"id": "b", "text": "ACE inhibitors are preferred during pregnancy."}, {"id": "c", "text": "Hydration should be restricted in orthostasis."}, {"id": "d", "text": "Oral-only delayed treatment is recommended."}]'::jsonb, '["a"]'::jsonb, 'Correct because ACE inhibitors (e.g., lisinopril) can cause dry cough and are contraindicated in pregnancy. Screen for pregnancy status and cough intolerance.', 'Hypertension Hypotension CO SV - NCLEX', false, 36, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "ARB specifics" in Hypertension, Hypotension, CO & SV. Which statement is correct?', 'The nurse is reviewing "ARB specifics" in Hypertension, Hypotension, CO & SV. Which statement is correct?', '[{"id": "a", "text": "ARBs are only emergency IV drugs."}, {"id": "b", "text": "Use ARB substitution when ACE cough limits adherence."}, {"id": "c", "text": "Warm flushed skin with high urine output is hallmark."}, {"id": "d", "text": "Any low BP without symptoms is always shock."}]'::jsonb, '["b"]'::jsonb, 'Correct because ARBs (e.g., losartan) are used if ACE inhibitors are not tolerated and do not cause cough per note. Use ARB substitution when ACE cough limits adherence.', 'Hypertension Hypotension CO SV - NCLEX', false, 37, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Thiazide/CCB/beta-blocker roles" in Hypertension, Hypotension, CO & SV?', 'Which clinical judgment is most accurate regarding "Thiazide/CCB/beta-blocker roles" in Hypertension, Hypotension, CO & SV?', '[{"id": "a", "text": "Standing position is preferred in severe hypotension."}, {"id": "b", "text": "Beta-blockers increase contractility."}, {"id": "c", "text": "Match medication mechanism to hemodynamic target."}, {"id": "d", "text": "Diuresis is first-line for hypovolemic hypotension."}]'::jsonb, '["c"]'::jsonb, 'Correct because Thiazides are first-line for most patients, CCBs cause vasodilation, and beta-blockers reduce HR/contractility. Match medication mechanism to hemodynamic target.', 'Hypertension Hypotension CO SV - NCLEX', false, 38, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Hypertensive emergency treatment" in Hypertension, Hypotension, CO & SV?', 'In rapid prioritization, which statement is most consistent with "Hypertensive emergency treatment" in Hypertension, Hypotension, CO & SV?', '[{"id": "a", "text": "HR has no relation to CO in this table."}, {"id": "b", "text": "Emergency is distinct from asymptomatic severe HTN."}, {"id": "c", "text": "Oral-only delayed treatment is recommended."}, {"id": "d", "text": "No organ damage assessment is needed."}]'::jsonb, '["b"]'::jsonb, 'Correct because Hypertensive emergency with organ damage requires IV antihypertensives such as nicardipine, labetalol, or nitroprusside. Treat with controlled IV reduction while monitoring perfusion.', 'Hypertension Hypotension CO SV - NCLEX', false, 39, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "MAP reduction limit" in Hypertension, Hypotension, CO & SV would the nurse recognize as correct?', 'Which conclusion about "MAP reduction limit" in Hypertension, Hypotension, CO & SV would the nurse recognize as correct?', '[{"id": "a", "text": "First-hour MAP reduction cap is 25%."}, {"id": "b", "text": "Drop must occur after 30 minutes."}, {"id": "c", "text": "MAP has no role in emergency treatment."}, {"id": "d", "text": "Preload is unaffected by fluid status."}]'::jsonb, '["a"]'::jsonb, 'Correct because In hypertensive emergency, MAP should not be reduced by more than 25% in the first hour. Avoid overcorrection that can cause organ hypoperfusion.', 'Hypertension Hypotension CO SV - NCLEX', false, 40, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Hypertension, Hypotension, CO & SV note, which statement about "Hypotension definition" is most accurate?', 'According to the Hypertension, Hypotension, CO & SV note, which statement about "Hypotension definition" is most accurate?', '[{"id": "a", "text": "Because perfusion appears stable, immediate reassessment is unnecessary."}, {"id": "b", "text": "Any low BP without symptoms is always shock."}, {"id": "c", "text": "Aggressive BP shifts are always preferred regardless of organ perfusion."}, {"id": "d", "text": "Treat symptomatic low BP rapidly to protect organ perfusion."}]'::jsonb, '["d"]'::jsonb, 'Correct because Hypotension is systolic <90 or diastolic <60 and is significant when symptoms or hypoperfusion are present. Treat symptomatic low BP rapidly to protect organ perfusion.', 'Hypertension Hypotension CO SV - NCLEX', false, 41, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Hypotension types and causes" in Hypertension, Hypotension, CO & SV. Which statement is correct?', 'The nurse is reviewing "Hypotension types and causes" in Hypertension, Hypotension, CO & SV. Which statement is correct?', '[{"id": "a", "text": "Warm flushed skin with high urine output is hallmark."}, {"id": "b", "text": "Identify subtype/cause to guide targeted therapy."}, {"id": "c", "text": "Only neurogenic hypotension exists."}, {"id": "d", "text": "Standing position is preferred in severe hypotension."}]'::jsonb, '["b"]'::jsonb, 'Correct because Types listed are orthostatic, hypovolemic, neurogenic, and cardiogenic; causes include bleeding/dehydration, HF, sepsis, medications, and Addison disease. Identify subtype/cause to guide targeted therapy.', 'Hypertension Hypotension CO SV - NCLEX', false, 42, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Orthostatic criteria" in Hypertension, Hypotension, CO & SV?', 'Which clinical judgment is most accurate regarding "Orthostatic criteria" in Hypertension, Hypotension, CO & SV?', '[{"id": "a", "text": "Diastolic drop threshold is 10 mmHg."}, {"id": "b", "text": "Drop must occur after 30 minutes."}, {"id": "c", "text": "Orthostatic criteria require HR rise only."}, {"id": "d", "text": "Bradycardia always raises CO."}]'::jsonb, '["a"]'::jsonb, 'Correct because Orthostatic hypotension is drop ≥20 systolic or ≥10 diastolic within 3 minutes of standing. Measure postural vitals correctly before labeling orthostasis.', 'Hypertension Hypotension CO SV - NCLEX', false, 43, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Orthostatic management" in Hypertension, Hypotension, CO & SV?', 'In rapid prioritization, which statement is most consistent with "Orthostatic management" in Hypertension, Hypotension, CO & SV?', '[{"id": "a", "text": "Prevent falls and syncope with positional safety teaching."}, {"id": "b", "text": "Because perfusion appears stable, immediate reassessment is unnecessary."}, {"id": "c", "text": "Hydration should be restricted in orthostasis."}, {"id": "d", "text": "Aggressive BP shifts are always preferred regardless of organ perfusion."}]'::jsonb, '["a"]'::jsonb, 'Correct because Nursing actions include dangling legs before standing, slow position changes, and adequate hydration. Prevent falls and syncope with positional safety teaching.', 'Hypertension Hypotension CO SV - NCLEX', false, 44, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Hypotension symptoms" in Hypertension, Hypotension, CO & SV would the nurse recognize as correct?', 'Which conclusion about "Hypotension symptoms" in Hypertension, Hypotension, CO & SV would the nurse recognize as correct?', '[{"id": "a", "text": "Warm flushed skin with high urine output is hallmark."}, {"id": "b", "text": "Aggressive BP shifts are always preferred regardless of organ perfusion."}, {"id": "c", "text": "Because perfusion appears stable, immediate reassessment is unnecessary."}, {"id": "d", "text": "Symptoms include dizziness, syncope, blurred vision, confusion, compensatory tachycardia, cool pale skin, and low urine output."}]'::jsonb, '["d"]'::jsonb, 'Correct because Symptoms include dizziness, syncope, blurred vision, confusion, compensatory tachycardia, cool pale skin, and low urine output. Trend neuro, skin, pulse, and urine output for perfusion decline.', 'Hypertension Hypotension CO SV - NCLEX', false, 45, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Hypertension, Hypotension, CO & SV note, which statement about "Hypotension treatment" is most accurate?', 'According to the Hypertension, Hypotension, CO & SV note, which statement about "Hypotension treatment" is most accurate?', '[{"id": "a", "text": "Aggressive BP shifts are always preferred regardless of organ perfusion."}, {"id": "b", "text": "Restore circulating volume and perfusion while preventing recurrent drops."}, {"id": "c", "text": "Because perfusion appears stable, immediate reassessment is unnecessary."}, {"id": "d", "text": "Standing position is preferred in severe hypotension."}]'::jsonb, '["b"]'::jsonb, 'Correct because Management includes treating cause, IV fluids or blood products for hypovolemia, vasopressors for severe cases, supine position with legs elevated, and slow postural changes. Restore circulating volume and perfusion while preventing recurrent drops.', 'Hypertension Hypotension CO SV - NCLEX', false, 46, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "CO factors: heart rate" in Hypertension, Hypotension, CO & SV. Which statement is correct?', 'The nurse is reviewing "CO factors: heart rate" in Hypertension, Hypotension, CO & SV. Which statement is correct?', '[{"id": "a", "text": "HR has no relation to CO in this table."}, {"id": "b", "text": "Beta-blockers can lower CO via HR effects in table."}, {"id": "c", "text": "Normal BP is listed as under 140/90."}, {"id": "d", "text": "MAP 55 is acceptable organ perfusion."}]'::jsonb, '["b"]'::jsonb, 'Correct because CO can increase with tachycardia/epinephrine and decrease with bradycardia/beta-blockers per table. Evaluate whether HR changes are compensatory or harmful to perfusion.', 'Hypertension Hypotension CO SV - NCLEX', false, 47, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "CO factors: preload" in Hypertension, Hypotension, CO & SV?', 'Which clinical judgment is most accurate regarding "CO factors: preload" in Hypertension, Hypotension, CO & SV?', '[{"id": "a", "text": "Heart rate does not affect CO."}, {"id": "b", "text": "Hemorrhage lowers preload in table."}, {"id": "c", "text": "SVR has no influence on BP."}, {"id": "d", "text": "Preload is unaffected by fluid status."}]'::jsonb, '["b"]'::jsonb, 'Correct because Preload increase with fluid volume can raise CO; dehydration/hemorrhage lower preload and CO. Volume assessment is central in hypotension and shock states.', 'Hypertension Hypotension CO SV - NCLEX', false, 48, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "CO factors: afterload/contractility" in Hypertension, Hypotension, CO & SV?', 'In rapid prioritization, which statement is most consistent with "CO factors: afterload/contractility" in Hypertension, Hypotension, CO & SV?', '[{"id": "a", "text": "Heart rate does not affect CO."}, {"id": "b", "text": "Vasoconstriction always increases CO."}, {"id": "c", "text": "CO equals MAP divided by pulse pressure."}, {"id": "d", "text": "Higher SVR can reduce CO in the table context."}]'::jsonb, '["d"]'::jsonb, 'Correct because Vasodilation (lower SVR) can improve CO while vasoconstriction (higher SVR) can reduce CO; contractility rises with digoxin/epinephrine and falls with HF/MI. Balance vascular tone and contractility when optimizing output.', 'Hypertension Hypotension CO SV - NCLEX', false, 49, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "NCLEX MAP warning" in Hypertension, Hypotension, CO & SV would the nurse recognize as correct?', 'Which conclusion about "NCLEX MAP warning" in Hypertension, Hypotension, CO & SV would the nurse recognize as correct?', '[{"id": "a", "text": "Immediate BP support is prioritized."}, {"id": "b", "text": "No action needed unless MAP <20."}, {"id": "c", "text": "MAP 55 is acceptable organ perfusion."}, {"id": "d", "text": "SVR is defined as oxygen saturation."}]'::jsonb, '["a"]'::jsonb, 'Correct because MAP below 60 mmHg means organs are at risk of ischemia and immediate BP/oxygenation support is priority. Treat MAP <60 as urgent perfusion threat.', 'Hypertension Hypotension CO SV - NCLEX', false, 50, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "BP formula" in Hypertension, Hypotension, CO & SV are correct? (Select all that apply)', 'Which statements about "BP formula" in Hypertension, Hypotension, CO & SV are correct? (Select all that apply)', '[{"id": "a", "text": "Rising SVR can increase BP when CO constant."}, {"id": "b", "text": "BP equals HR minus SV."}, {"id": "c", "text": "BP depends on both CO and SVR."}, {"id": "d", "text": "Falling CO can lower BP if SVR unchanged."}, {"id": "e", "text": "SVR has no influence on BP."}]'::jsonb, '["a", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Blood pressure is determined by cardiac output multiplied by systemic vascular resistance (BP = CO × SVR).', 'Hypertension Hypotension CO SV - NCLEX', true, 51, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Hypertension, Hypotension, CO & SV, which findings or actions relate to "CO formula"? (Select all that apply)', 'For Hypertension, Hypotension, CO & SV, which findings or actions relate to "CO formula"? (Select all that apply)', '[{"id": "a", "text": "CO equals MAP divided by pulse pressure."}, {"id": "b", "text": "Heart rate does not affect CO."}, {"id": "c", "text": "Changes in either HR or SV change CO."}, {"id": "d", "text": "Formula is explicitly provided in note."}, {"id": "e", "text": "CO combines HR and SV."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Cardiac output equals stroke volume times heart rate (CO = SV × HR).', 'Hypertension Hypotension CO SV - NCLEX', true, 52, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "MAP formula and normal" in Hypertension, Hypotension, CO & SV? (Select all that apply)', 'The nurse is planning care. Which items apply to "MAP formula and normal" in Hypertension, Hypotension, CO & SV? (Select all that apply)', '[{"id": "a", "text": "MAP is calculated as SBP + DBP divided by 2."}, {"id": "b", "text": "Normal MAP range listed is 70–100."}, {"id": "c", "text": "Normal MAP is listed as 30–50."}, {"id": "d", "text": "MAP formula weights diastolic pressure twice."}, {"id": "e", "text": "MAP interpretation is key for perfusion."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: MAP is calculated as (2×DBP + SBP) ÷ 3 and normal range listed is 70–100 mmHg.', 'Hypertension Hypotension CO SV - NCLEX', true, 53, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Core definitions" in Hypertension, Hypotension, CO & SV? (Select all that apply)', 'Which of the following are consistent with "Core definitions" in Hypertension, Hypotension, CO & SV? (Select all that apply)', '[{"id": "a", "text": "Afterload is resistance to ejection."}, {"id": "b", "text": "Preload is venous return/stretch."}, {"id": "c", "text": "Afterload means venous return volume."}, {"id": "d", "text": "SV is blood volume pumped per beat."}, {"id": "e", "text": "SVR is defined as oxygen saturation."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: BP is force against artery walls, CO is blood pumped per minute by LV, SV is blood per beat, SVR is resistance to LV ejection, preload is venous return stretch, afterload is resistance to ejection.', 'Hypertension Hypotension CO SV - NCLEX', true, 54, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "HTN staging normal/elevated" in Hypertension, Hypotension, CO & SV? (Select all that apply)', 'During reassessment, which observations align with "HTN staging normal/elevated" in Hypertension, Hypotension, CO & SV? (Select all that apply)', '[{"id": "a", "text": "Normal is below 120/80."}, {"id": "b", "text": "Elevated is not yet stage 1."}, {"id": "c", "text": "Normal BP is listed as under 140/90."}, {"id": "d", "text": "Elevated BP requires DBP over 90."}, {"id": "e", "text": "Elevated has SBP 120–129 with DBP <80."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: Normal BP is <120/<80 and elevated is 120–129 systolic with diastolic <80.', 'Hypertension Hypotension CO SV - NCLEX', true, 55, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "HTN stages 1 and 2" in Hypertension, Hypotension, CO & SV are correct? (Select all that apply)', 'Which statements about "HTN stages 1 and 2" in Hypertension, Hypotension, CO & SV are correct? (Select all that apply)', '[{"id": "a", "text": "Diastolic thresholds are 80–89 for stage 1 and ≥90 for stage 2."}, {"id": "b", "text": "Stage 1 includes 130–139 systolic."}, {"id": "c", "text": "Stage 1 starts at SBP 150."}, {"id": "d", "text": "Stage 2 begins at 140 systolic."}, {"id": "e", "text": "Stage 2 requires SBP >200."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: Stage 1 HTN is 130–139 or 80–89; stage 2 is ≥140 or ≥90.', 'Hypertension Hypotension CO SV - NCLEX', true, 56, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Hypertension, Hypotension, CO & SV, which findings or actions relate to "Hypertensive crisis threshold"? (Select all that apply)', 'For Hypertension, Hypotension, CO & SV, which findings or actions relate to "Hypertensive crisis threshold"? (Select all that apply)', '[{"id": "a", "text": "Crisis starts at 150/90."}, {"id": "b", "text": "Crisis is higher risk than stage 2."}, {"id": "c", "text": "Crisis requires low BP."}, {"id": "d", "text": "Crisis threshold includes systolic above 180."}, {"id": "e", "text": "Crisis threshold includes diastolic above 120."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Hypertensive crisis is listed as BP >180/>120.', 'Hypertension Hypotension CO SV - NCLEX', true, 57, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "HTN risk factors" in Hypertension, Hypotension, CO & SV? (Select all that apply)', 'The nurse is planning care. Which items apply to "HTN risk factors" in Hypertension, Hypotension, CO & SV? (Select all that apply)', '[{"id": "a", "text": "Stress has no relation to HTN."}, {"id": "b", "text": "Smoking and obesity are modifiable risks."}, {"id": "c", "text": "High sodium intake is listed modifiable risk."}, {"id": "d", "text": "Family history is listed non-modifiable risk."}, {"id": "e", "text": "Age is modifiable."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Non-modifiable risks include age, family history, and race; modifiable include obesity, smoking, high sodium diet, sedentary lifestyle, alcohol, and stress.', 'Hypertension Hypotension CO SV - NCLEX', true, 58, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "HTN complications" in Hypertension, Hypotension, CO & SV? (Select all that apply)', 'Which of the following are consistent with "HTN complications" in Hypertension, Hypotension, CO & SV? (Select all that apply)', '[{"id": "a", "text": "Only skin complications are listed."}, {"id": "b", "text": "Retinal damage is listed complication."}, {"id": "c", "text": "CKD is listed complication."}, {"id": "d", "text": "Stroke and MI are listed complications."}, {"id": "e", "text": "HTN has no end-organ complications."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Complications listed are stroke, MI, heart failure, CKD, and retinal damage.', 'Hypertension Hypotension CO SV - NCLEX', true, 59, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Lifestyle HTN management" in Hypertension, Hypotension, CO & SV? (Select all that apply)', 'During reassessment, which observations align with "Lifestyle HTN management" in Hypertension, Hypotension, CO & SV? (Select all that apply)', '[{"id": "a", "text": "Smoking cessation is part of plan."}, {"id": "b", "text": "Exercise and weight loss are recommended."}, {"id": "c", "text": "DASH diet is recommended."}, {"id": "d", "text": "High-salt diet is recommended for HTN."}, {"id": "e", "text": "Sedentary rest is first-line lifestyle."}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Correct selections align with note-based facts: Lifestyle management includes DASH (lower sodium/higher potassium), exercise, weight loss, and smoking cessation.', 'Hypertension Hypotension CO SV - NCLEX', true, 60, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "ACE inhibitor specifics" in Hypertension, Hypotension, CO & SV are correct? (Select all that apply)', 'Which statements about "ACE inhibitor specifics" in Hypertension, Hypotension, CO & SV are correct? (Select all that apply)', '[{"id": "a", "text": "ACE inhibitors are preferred during pregnancy."}, {"id": "b", "text": "Lisinopril is listed ACE example."}, {"id": "c", "text": "ACE inhibitors have no cough risk."}, {"id": "d", "text": "ACE inhibitors are contraindicated in pregnancy."}, {"id": "e", "text": "Dry cough is a listed ACE inhibitor side effect."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: ACE inhibitors (e.g., lisinopril) can cause dry cough and are contraindicated in pregnancy.', 'Hypertension Hypotension CO SV - NCLEX', true, 61, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Hypertension, Hypotension, CO & SV, which findings or actions relate to "ARB specifics"? (Select all that apply)', 'For Hypertension, Hypotension, CO & SV, which findings or actions relate to "ARB specifics"? (Select all that apply)', '[{"id": "a", "text": "Losartan is listed ARB example."}, {"id": "b", "text": "ARBs are only emergency IV drugs."}, {"id": "c", "text": "ARBs are used when ACE not tolerated."}, {"id": "d", "text": "ARBs worsen ACE cough."}, {"id": "e", "text": "No-cough advantage is highlighted."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: ARBs (e.g., losartan) are used if ACE inhibitors are not tolerated and do not cause cough per note.', 'Hypertension Hypotension CO SV - NCLEX', true, 62, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Thiazide/CCB/beta-blocker roles" in Hypertension, Hypotension, CO & SV? (Select all that apply)', 'The nurse is planning care. Which items apply to "Thiazide/CCB/beta-blocker roles" in Hypertension, Hypotension, CO & SV? (Select all that apply)', '[{"id": "a", "text": "Amlodipine is listed for vasodilation."}, {"id": "b", "text": "Beta-blockers increase contractility."}, {"id": "c", "text": "Metoprolol lowers HR and contractility."}, {"id": "d", "text": "CCBs are listed as preload boosters."}, {"id": "e", "text": "HCTZ is listed first-line for many patients."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Thiazides are first-line for most patients, CCBs cause vasodilation, and beta-blockers reduce HR/contractility.', 'Hypertension Hypotension CO SV - NCLEX', true, 63, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Hypertensive emergency treatment" in Hypertension, Hypotension, CO & SV? (Select all that apply)', 'Which of the following are consistent with "Hypertensive emergency treatment" in Hypertension, Hypotension, CO & SV? (Select all that apply)', '[{"id": "a", "text": "Organ damage presence defines emergency context."}, {"id": "b", "text": "Emergency is distinct from asymptomatic severe HTN."}, {"id": "c", "text": "No organ damage assessment is needed."}, {"id": "d", "text": "Oral-only delayed treatment is recommended."}, {"id": "e", "text": "IV nicardipine/labetalol/nitroprusside are listed."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: Hypertensive emergency with organ damage requires IV antihypertensives such as nicardipine, labetalol, or nitroprusside.', 'Hypertension Hypotension CO SV - NCLEX', true, 64, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "MAP reduction limit" in Hypertension, Hypotension, CO & SV? (Select all that apply)', 'During reassessment, which observations align with "MAP reduction limit" in Hypertension, Hypotension, CO & SV? (Select all that apply)', '[{"id": "a", "text": "Reduce MAP by 60% in first hour."}, {"id": "b", "text": "Rapid excessive reduction is unsafe."}, {"id": "c", "text": "First-hour MAP reduction cap is 25%."}, {"id": "d", "text": "MAP-guided titration is emphasized."}, {"id": "e", "text": "MAP has no role in emergency treatment."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: In hypertensive emergency, MAP should not be reduced by more than 25% in the first hour.', 'Hypertension Hypotension CO SV - NCLEX', true, 65, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Hypotension definition" in Hypertension, Hypotension, CO & SV are correct? (Select all that apply)', 'Which statements about "Hypotension definition" in Hypertension, Hypotension, CO & SV are correct? (Select all that apply)', '[{"id": "a", "text": "Any low BP without symptoms is always shock."}, {"id": "b", "text": "DBP under 60 is hypotension."}, {"id": "c", "text": "Clinical significance depends on perfusion impact."}, {"id": "d", "text": "SBP under 90 is hypotension."}, {"id": "e", "text": "Hypotension is defined as SBP under 130."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Hypotension is systolic <90 or diastolic <60 and is significant when symptoms or hypoperfusion are present.', 'Hypertension Hypotension CO SV - NCLEX', true, 66, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Hypertension, Hypotension, CO & SV, which findings or actions relate to "Hypotension types and causes"? (Select all that apply)', 'For Hypertension, Hypotension, CO & SV, which findings or actions relate to "Hypotension types and causes"? (Select all that apply)', '[{"id": "a", "text": "Only neurogenic hypotension exists."}, {"id": "b", "text": "Meds and Addison disease are listed causes."}, {"id": "c", "text": "Orthostatic and hypovolemic are listed types."}, {"id": "d", "text": "Sepsis cannot cause hypotension."}, {"id": "e", "text": "Sepsis and HF are listed causes."}]'::jsonb, '["b", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Types listed are orthostatic, hypovolemic, neurogenic, and cardiogenic; causes include bleeding/dehydration, HF, sepsis, medications, and Addison disease.', 'Hypertension Hypotension CO SV - NCLEX', true, 67, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Orthostatic criteria" in Hypertension, Hypotension, CO & SV? (Select all that apply)', 'The nurse is planning care. Which items apply to "Orthostatic criteria" in Hypertension, Hypotension, CO & SV? (Select all that apply)', '[{"id": "a", "text": "Timing window is within 3 minutes of standing."}, {"id": "b", "text": "Diastolic drop threshold is 10 mmHg."}, {"id": "c", "text": "Orthostatic criteria require HR rise only."}, {"id": "d", "text": "Drop must occur after 30 minutes."}, {"id": "e", "text": "Systolic drop threshold is 20 mmHg."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: Orthostatic hypotension is drop ≥20 systolic or ≥10 diastolic within 3 minutes of standing.', 'Hypertension Hypotension CO SV - NCLEX', true, 68, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Orthostatic management" in Hypertension, Hypotension, CO & SV? (Select all that apply)', 'Which of the following are consistent with "Orthostatic management" in Hypertension, Hypotension, CO & SV? (Select all that apply)', '[{"id": "a", "text": "Dangle legs before standing is listed."}, {"id": "b", "text": "Hydration support is recommended."}, {"id": "c", "text": "Slow position changes are recommended."}, {"id": "d", "text": "Rapid standing is preferred."}, {"id": "e", "text": "Hydration should be restricted in orthostasis."}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Correct selections align with note-based facts: Nursing actions include dangling legs before standing, slow position changes, and adequate hydration.', 'Hypertension Hypotension CO SV - NCLEX', true, 69, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Hypotension symptoms" in Hypertension, Hypotension, CO & SV? (Select all that apply)', 'During reassessment, which observations align with "Hypotension symptoms" in Hypertension, Hypotension, CO & SV? (Select all that apply)', '[{"id": "a", "text": "Bradycardia is always present."}, {"id": "b", "text": "Low urine output is listed symptom."}, {"id": "c", "text": "Warm flushed skin with high urine output is hallmark."}, {"id": "d", "text": "Cool pale skin and tachycardia are listed."}, {"id": "e", "text": "Syncope/dizziness are listed symptoms."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Symptoms include dizziness, syncope, blurred vision, confusion, compensatory tachycardia, cool pale skin, and low urine output.', 'Hypertension Hypotension CO SV - NCLEX', true, 70, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Hypotension treatment" in Hypertension, Hypotension, CO & SV are correct? (Select all that apply)', 'Which statements about "Hypotension treatment" in Hypertension, Hypotension, CO & SV are correct? (Select all that apply)', '[{"id": "a", "text": "Diuresis is first-line for hypovolemic hypotension."}, {"id": "b", "text": "Norepinephrine/dopamine listed for severe hypotension."}, {"id": "c", "text": "Standing position is preferred in severe hypotension."}, {"id": "d", "text": "Supine with legs elevated is listed positioning."}, {"id": "e", "text": "IV fluids/blood products used if hypovolemic."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Management includes treating cause, IV fluids or blood products for hypovolemia, vasopressors for severe cases, supine position with legs elevated, and slow postural changes.', 'Hypertension Hypotension CO SV - NCLEX', true, 71, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Hypertension, Hypotension, CO & SV, which findings or actions relate to "CO factors: heart rate"? (Select all that apply)', 'For Hypertension, Hypotension, CO & SV, which findings or actions relate to "CO factors: heart rate"? (Select all that apply)', '[{"id": "a", "text": "Bradycardia can lower CO in table."}, {"id": "b", "text": "HR has no relation to CO in this table."}, {"id": "c", "text": "Beta-blockers can lower CO via HR effects in table."}, {"id": "d", "text": "Bradycardia always raises CO."}, {"id": "e", "text": "Tachycardia and epinephrine can raise CO in table."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: CO can increase with tachycardia/epinephrine and decrease with bradycardia/beta-blockers per table.', 'Hypertension Hypotension CO SV - NCLEX', true, 72, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "CO factors: preload" in Hypertension, Hypotension, CO & SV? (Select all that apply)', 'The nurse is planning care. Which items apply to "CO factors: preload" in Hypertension, Hypotension, CO & SV? (Select all that apply)', '[{"id": "a", "text": "Preload is unaffected by fluid status."}, {"id": "b", "text": "Hemorrhage lowers preload in table."}, {"id": "c", "text": "Higher fluid volume can increase preload/CO."}, {"id": "d", "text": "Dehydration lowers preload in table."}, {"id": "e", "text": "Hemorrhage raises preload."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Preload increase with fluid volume can raise CO; dehydration/hemorrhage lower preload and CO.', 'Hypertension Hypotension CO SV - NCLEX', true, 73, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "CO factors: afterload/contractility" in Hypertension, Hypotension, CO & SV? (Select all that apply)', 'Which of the following are consistent with "CO factors: afterload/contractility" in Hypertension, Hypotension, CO & SV? (Select all that apply)', '[{"id": "a", "text": "Higher SVR can reduce CO in the table context."}, {"id": "b", "text": "Vasoconstriction always increases CO."}, {"id": "c", "text": "Digoxin/epinephrine increase contractility in table."}, {"id": "d", "text": "HF/MI decrease contractility in table."}, {"id": "e", "text": "HF improves contractility."}]'::jsonb, '["a", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Vasodilation (lower SVR) can improve CO while vasoconstriction (higher SVR) can reduce CO; contractility rises with digoxin/epinephrine and falls with HF/MI.', 'Hypertension Hypotension CO SV - NCLEX', true, 74, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "NCLEX MAP warning" in Hypertension, Hypotension, CO & SV? (Select all that apply)', 'During reassessment, which observations align with "NCLEX MAP warning" in Hypertension, Hypotension, CO & SV? (Select all that apply)', '[{"id": "a", "text": "MAP 55 is acceptable organ perfusion."}, {"id": "b", "text": "MAP <60 is ischemia risk in note tip."}, {"id": "c", "text": "Oxygenation support is also prioritized."}, {"id": "d", "text": "Immediate BP support is prioritized."}, {"id": "e", "text": "No action needed unless MAP <20."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: MAP below 60 mmHg means organs are at risk of ischemia and immediate BP/oxygenation support is priority.', 'Hypertension Hypotension CO SV - NCLEX', true, 75, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "BP formula" in Hypertension, Hypotension, CO & SV are correct? (Select all that apply)', 'Which statements about "BP formula" in Hypertension, Hypotension, CO & SV are correct? (Select all that apply)', '[{"id": "a", "text": "Falling CO can lower BP if SVR unchanged."}, {"id": "b", "text": "Rising SVR can increase BP when CO constant."}, {"id": "c", "text": "BP depends on both CO and SVR."}, {"id": "d", "text": "SVR has no influence on BP."}, {"id": "e", "text": "BP equals HR minus SV."}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Correct selections align with note-based facts: Blood pressure is determined by cardiac output multiplied by systemic vascular resistance (BP = CO × SVR).', 'Hypertension Hypotension CO SV - NCLEX', true, 76, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Hypertension, Hypotension, CO & SV, which findings or actions relate to "CO formula"? (Select all that apply)', 'For Hypertension, Hypotension, CO & SV, which findings or actions relate to "CO formula"? (Select all that apply)', '[{"id": "a", "text": "CO combines HR and SV."}, {"id": "b", "text": "Changes in either HR or SV change CO."}, {"id": "c", "text": "Formula is explicitly provided in note."}, {"id": "d", "text": "Heart rate does not affect CO."}, {"id": "e", "text": "CO equals MAP divided by pulse pressure."}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Correct selections align with note-based facts: Cardiac output equals stroke volume times heart rate (CO = SV × HR).', 'Hypertension Hypotension CO SV - NCLEX', true, 77, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "MAP formula and normal" in Hypertension, Hypotension, CO & SV? (Select all that apply)', 'The nurse is planning care. Which items apply to "MAP formula and normal" in Hypertension, Hypotension, CO & SV? (Select all that apply)', '[{"id": "a", "text": "Normal MAP is listed as 30–50."}, {"id": "b", "text": "MAP formula weights diastolic pressure twice."}, {"id": "c", "text": "Normal MAP range listed is 70–100."}, {"id": "d", "text": "MAP interpretation is key for perfusion."}, {"id": "e", "text": "MAP is calculated as SBP + DBP divided by 2."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: MAP is calculated as (2×DBP + SBP) ÷ 3 and normal range listed is 70–100 mmHg.', 'Hypertension Hypotension CO SV - NCLEX', true, 78, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Core definitions" in Hypertension, Hypotension, CO & SV? (Select all that apply)', 'Which of the following are consistent with "Core definitions" in Hypertension, Hypotension, CO & SV? (Select all that apply)', '[{"id": "a", "text": "Afterload is resistance to ejection."}, {"id": "b", "text": "SVR is defined as oxygen saturation."}, {"id": "c", "text": "Afterload means venous return volume."}, {"id": "d", "text": "SV is blood volume pumped per beat."}, {"id": "e", "text": "Preload is venous return/stretch."}]'::jsonb, '["a", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: BP is force against artery walls, CO is blood pumped per minute by LV, SV is blood per beat, SVR is resistance to LV ejection, preload is venous return stretch, afterload is resistance to ejection.', 'Hypertension Hypotension CO SV - NCLEX', true, 79, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "HTN staging normal/elevated" in Hypertension, Hypotension, CO & SV? (Select all that apply)', 'During reassessment, which observations align with "HTN staging normal/elevated" in Hypertension, Hypotension, CO & SV? (Select all that apply)', '[{"id": "a", "text": "Elevated is not yet stage 1."}, {"id": "b", "text": "Normal BP is listed as under 140/90."}, {"id": "c", "text": "Elevated has SBP 120–129 with DBP <80."}, {"id": "d", "text": "Normal is below 120/80."}, {"id": "e", "text": "Elevated BP requires DBP over 90."}]'::jsonb, '["a", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Normal BP is <120/<80 and elevated is 120–129 systolic with diastolic <80.', 'Hypertension Hypotension CO SV - NCLEX', true, 80, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "HTN stages 1 and 2" in Hypertension, Hypotension, CO & SV are correct? (Select all that apply)', 'Which statements about "HTN stages 1 and 2" in Hypertension, Hypotension, CO & SV are correct? (Select all that apply)', '[{"id": "a", "text": "Stage 1 includes 130–139 systolic."}, {"id": "b", "text": "Stage 2 begins at 140 systolic."}, {"id": "c", "text": "Stage 1 starts at SBP 150."}, {"id": "d", "text": "Stage 2 requires SBP >200."}, {"id": "e", "text": "Diastolic thresholds are 80–89 for stage 1 and ≥90 for stage 2."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: Stage 1 HTN is 130–139 or 80–89; stage 2 is ≥140 or ≥90.', 'Hypertension Hypotension CO SV - NCLEX', true, 81, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Hypertension, Hypotension, CO & SV, which findings or actions relate to "Hypertensive crisis threshold"? (Select all that apply)', 'For Hypertension, Hypotension, CO & SV, which findings or actions relate to "Hypertensive crisis threshold"? (Select all that apply)', '[{"id": "a", "text": "Crisis is higher risk than stage 2."}, {"id": "b", "text": "Crisis requires low BP."}, {"id": "c", "text": "Crisis starts at 150/90."}, {"id": "d", "text": "Crisis threshold includes diastolic above 120."}, {"id": "e", "text": "Crisis threshold includes systolic above 180."}]'::jsonb, '["a", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Hypertensive crisis is listed as BP >180/>120.', 'Hypertension Hypotension CO SV - NCLEX', true, 82, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "HTN risk factors" in Hypertension, Hypotension, CO & SV? (Select all that apply)', 'The nurse is planning care. Which items apply to "HTN risk factors" in Hypertension, Hypotension, CO & SV? (Select all that apply)', '[{"id": "a", "text": "Family history is listed non-modifiable risk."}, {"id": "b", "text": "High sodium intake is listed modifiable risk."}, {"id": "c", "text": "Smoking and obesity are modifiable risks."}, {"id": "d", "text": "Stress has no relation to HTN."}, {"id": "e", "text": "Age is modifiable."}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Correct selections align with note-based facts: Non-modifiable risks include age, family history, and race; modifiable include obesity, smoking, high sodium diet, sedentary lifestyle, alcohol, and stress.', 'Hypertension Hypotension CO SV - NCLEX', true, 83, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "HTN complications" in Hypertension, Hypotension, CO & SV? (Select all that apply)', 'Which of the following are consistent with "HTN complications" in Hypertension, Hypotension, CO & SV? (Select all that apply)', '[{"id": "a", "text": "HTN has no end-organ complications."}, {"id": "b", "text": "Only skin complications are listed."}, {"id": "c", "text": "CKD is listed complication."}, {"id": "d", "text": "Stroke and MI are listed complications."}, {"id": "e", "text": "Retinal damage is listed complication."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Complications listed are stroke, MI, heart failure, CKD, and retinal damage.', 'Hypertension Hypotension CO SV - NCLEX', true, 84, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Lifestyle HTN management" in Hypertension, Hypotension, CO & SV? (Select all that apply)', 'During reassessment, which observations align with "Lifestyle HTN management" in Hypertension, Hypotension, CO & SV? (Select all that apply)', '[{"id": "a", "text": "Sedentary rest is first-line lifestyle."}, {"id": "b", "text": "High-salt diet is recommended for HTN."}, {"id": "c", "text": "Exercise and weight loss are recommended."}, {"id": "d", "text": "DASH diet is recommended."}, {"id": "e", "text": "Smoking cessation is part of plan."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Lifestyle management includes DASH (lower sodium/higher potassium), exercise, weight loss, and smoking cessation.', 'Hypertension Hypotension CO SV - NCLEX', true, 85, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "ACE inhibitor specifics" in Hypertension, Hypotension, CO & SV are correct? (Select all that apply)', 'Which statements about "ACE inhibitor specifics" in Hypertension, Hypotension, CO & SV are correct? (Select all that apply)', '[{"id": "a", "text": "ACE inhibitors are contraindicated in pregnancy."}, {"id": "b", "text": "ACE inhibitors are preferred during pregnancy."}, {"id": "c", "text": "Dry cough is a listed ACE inhibitor side effect."}, {"id": "d", "text": "ACE inhibitors have no cough risk."}, {"id": "e", "text": "Lisinopril is listed ACE example."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: ACE inhibitors (e.g., lisinopril) can cause dry cough and are contraindicated in pregnancy.', 'Hypertension Hypotension CO SV - NCLEX', true, 86, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Hypertension, Hypotension, CO & SV, which findings or actions relate to "ARB specifics"? (Select all that apply)', 'For Hypertension, Hypotension, CO & SV, which findings or actions relate to "ARB specifics"? (Select all that apply)', '[{"id": "a", "text": "Losartan is listed ARB example."}, {"id": "b", "text": "ARBs worsen ACE cough."}, {"id": "c", "text": "ARBs are used when ACE not tolerated."}, {"id": "d", "text": "ARBs are only emergency IV drugs."}, {"id": "e", "text": "No-cough advantage is highlighted."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: ARBs (e.g., losartan) are used if ACE inhibitors are not tolerated and do not cause cough per note.', 'Hypertension Hypotension CO SV - NCLEX', true, 87, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Thiazide/CCB/beta-blocker roles" in Hypertension, Hypotension, CO & SV? (Select all that apply)', 'The nurse is planning care. Which items apply to "Thiazide/CCB/beta-blocker roles" in Hypertension, Hypotension, CO & SV? (Select all that apply)', '[{"id": "a", "text": "Metoprolol lowers HR and contractility."}, {"id": "b", "text": "HCTZ is listed first-line for many patients."}, {"id": "c", "text": "Beta-blockers increase contractility."}, {"id": "d", "text": "CCBs are listed as preload boosters."}, {"id": "e", "text": "Amlodipine is listed for vasodilation."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: Thiazides are first-line for most patients, CCBs cause vasodilation, and beta-blockers reduce HR/contractility.', 'Hypertension Hypotension CO SV - NCLEX', true, 88, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Hypertensive emergency treatment" in Hypertension, Hypotension, CO & SV? (Select all that apply)', 'Which of the following are consistent with "Hypertensive emergency treatment" in Hypertension, Hypotension, CO & SV? (Select all that apply)', '[{"id": "a", "text": "Oral-only delayed treatment is recommended."}, {"id": "b", "text": "Organ damage presence defines emergency context."}, {"id": "c", "text": "Emergency is distinct from asymptomatic severe HTN."}, {"id": "d", "text": "IV nicardipine/labetalol/nitroprusside are listed."}, {"id": "e", "text": "No organ damage assessment is needed."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Hypertensive emergency with organ damage requires IV antihypertensives such as nicardipine, labetalol, or nitroprusside.', 'Hypertension Hypotension CO SV - NCLEX', true, 89, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "MAP reduction limit" in Hypertension, Hypotension, CO & SV? (Select all that apply)', 'During reassessment, which observations align with "MAP reduction limit" in Hypertension, Hypotension, CO & SV? (Select all that apply)', '[{"id": "a", "text": "First-hour MAP reduction cap is 25%."}, {"id": "b", "text": "MAP has no role in emergency treatment."}, {"id": "c", "text": "Reduce MAP by 60% in first hour."}, {"id": "d", "text": "MAP-guided titration is emphasized."}, {"id": "e", "text": "Rapid excessive reduction is unsafe."}]'::jsonb, '["a", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: In hypertensive emergency, MAP should not be reduced by more than 25% in the first hour.', 'Hypertension Hypotension CO SV - NCLEX', true, 90, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Hypotension definition" in Hypertension, Hypotension, CO & SV are correct? (Select all that apply)', 'Which statements about "Hypotension definition" in Hypertension, Hypotension, CO & SV are correct? (Select all that apply)', '[{"id": "a", "text": "Clinical significance depends on perfusion impact."}, {"id": "b", "text": "Any low BP without symptoms is always shock."}, {"id": "c", "text": "DBP under 60 is hypotension."}, {"id": "d", "text": "Hypotension is defined as SBP under 130."}, {"id": "e", "text": "SBP under 90 is hypotension."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Hypotension is systolic <90 or diastolic <60 and is significant when symptoms or hypoperfusion are present.', 'Hypertension Hypotension CO SV - NCLEX', true, 91, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Hypertension, Hypotension, CO & SV, which findings or actions relate to "Hypotension types and causes"? (Select all that apply)', 'For Hypertension, Hypotension, CO & SV, which findings or actions relate to "Hypotension types and causes"? (Select all that apply)', '[{"id": "a", "text": "Sepsis cannot cause hypotension."}, {"id": "b", "text": "Only neurogenic hypotension exists."}, {"id": "c", "text": "Meds and Addison disease are listed causes."}, {"id": "d", "text": "Orthostatic and hypovolemic are listed types."}, {"id": "e", "text": "Sepsis and HF are listed causes."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Types listed are orthostatic, hypovolemic, neurogenic, and cardiogenic; causes include bleeding/dehydration, HF, sepsis, medications, and Addison disease.', 'Hypertension Hypotension CO SV - NCLEX', true, 92, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Orthostatic criteria" in Hypertension, Hypotension, CO & SV? (Select all that apply)', 'The nurse is planning care. Which items apply to "Orthostatic criteria" in Hypertension, Hypotension, CO & SV? (Select all that apply)', '[{"id": "a", "text": "Orthostatic criteria require HR rise only."}, {"id": "b", "text": "Timing window is within 3 minutes of standing."}, {"id": "c", "text": "Systolic drop threshold is 20 mmHg."}, {"id": "d", "text": "Diastolic drop threshold is 10 mmHg."}, {"id": "e", "text": "Drop must occur after 30 minutes."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Orthostatic hypotension is drop ≥20 systolic or ≥10 diastolic within 3 minutes of standing.', 'Hypertension Hypotension CO SV - NCLEX', true, 93, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Orthostatic management" in Hypertension, Hypotension, CO & SV? (Select all that apply)', 'Which of the following are consistent with "Orthostatic management" in Hypertension, Hypotension, CO & SV? (Select all that apply)', '[{"id": "a", "text": "Hydration support is recommended."}, {"id": "b", "text": "Hydration should be restricted in orthostasis."}, {"id": "c", "text": "Rapid standing is preferred."}, {"id": "d", "text": "Dangle legs before standing is listed."}, {"id": "e", "text": "Slow position changes are recommended."}]'::jsonb, '["a", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Nursing actions include dangling legs before standing, slow position changes, and adequate hydration.', 'Hypertension Hypotension CO SV - NCLEX', true, 94, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Hypotension symptoms" in Hypertension, Hypotension, CO & SV? (Select all that apply)', 'During reassessment, which observations align with "Hypotension symptoms" in Hypertension, Hypotension, CO & SV? (Select all that apply)', '[{"id": "a", "text": "Syncope/dizziness are listed symptoms."}, {"id": "b", "text": "Bradycardia is always present."}, {"id": "c", "text": "Cool pale skin and tachycardia are listed."}, {"id": "d", "text": "Low urine output is listed symptom."}, {"id": "e", "text": "Warm flushed skin with high urine output is hallmark."}]'::jsonb, '["a", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Symptoms include dizziness, syncope, blurred vision, confusion, compensatory tachycardia, cool pale skin, and low urine output.', 'Hypertension Hypotension CO SV - NCLEX', true, 95, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Hypotension treatment" in Hypertension, Hypotension, CO & SV are correct? (Select all that apply)', 'Which statements about "Hypotension treatment" in Hypertension, Hypotension, CO & SV are correct? (Select all that apply)', '[{"id": "a", "text": "Supine with legs elevated is listed positioning."}, {"id": "b", "text": "Diuresis is first-line for hypovolemic hypotension."}, {"id": "c", "text": "Standing position is preferred in severe hypotension."}, {"id": "d", "text": "IV fluids/blood products used if hypovolemic."}, {"id": "e", "text": "Norepinephrine/dopamine listed for severe hypotension."}]'::jsonb, '["a", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Management includes treating cause, IV fluids or blood products for hypovolemia, vasopressors for severe cases, supine position with legs elevated, and slow postural changes.', 'Hypertension Hypotension CO SV - NCLEX', true, 96, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Hypertension, Hypotension, CO & SV, which findings or actions relate to "CO factors: heart rate"? (Select all that apply)', 'For Hypertension, Hypotension, CO & SV, which findings or actions relate to "CO factors: heart rate"? (Select all that apply)', '[{"id": "a", "text": "Bradycardia can lower CO in table."}, {"id": "b", "text": "HR has no relation to CO in this table."}, {"id": "c", "text": "Bradycardia always raises CO."}, {"id": "d", "text": "Beta-blockers can lower CO via HR effects in table."}, {"id": "e", "text": "Tachycardia and epinephrine can raise CO in table."}]'::jsonb, '["a", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: CO can increase with tachycardia/epinephrine and decrease with bradycardia/beta-blockers per table.', 'Hypertension Hypotension CO SV - NCLEX', true, 97, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "CO factors: preload" in Hypertension, Hypotension, CO & SV? (Select all that apply)', 'The nurse is planning care. Which items apply to "CO factors: preload" in Hypertension, Hypotension, CO & SV? (Select all that apply)', '[{"id": "a", "text": "Hemorrhage raises preload."}, {"id": "b", "text": "Dehydration lowers preload in table."}, {"id": "c", "text": "Preload is unaffected by fluid status."}, {"id": "d", "text": "Higher fluid volume can increase preload/CO."}, {"id": "e", "text": "Hemorrhage lowers preload in table."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Preload increase with fluid volume can raise CO; dehydration/hemorrhage lower preload and CO.', 'Hypertension Hypotension CO SV - NCLEX', true, 98, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "CO factors: afterload/contractility" in Hypertension, Hypotension, CO & SV? (Select all that apply)', 'Which of the following are consistent with "CO factors: afterload/contractility" in Hypertension, Hypotension, CO & SV? (Select all that apply)', '[{"id": "a", "text": "HF/MI decrease contractility in table."}, {"id": "b", "text": "Digoxin/epinephrine increase contractility in table."}, {"id": "c", "text": "Higher SVR can reduce CO in the table context."}, {"id": "d", "text": "Vasoconstriction always increases CO."}, {"id": "e", "text": "HF improves contractility."}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Correct selections align with note-based facts: Vasodilation (lower SVR) can improve CO while vasoconstriction (higher SVR) can reduce CO; contractility rises with digoxin/epinephrine and falls with HF/MI.', 'Hypertension Hypotension CO SV - NCLEX', true, 99, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "NCLEX MAP warning" in Hypertension, Hypotension, CO & SV? (Select all that apply)', 'During reassessment, which observations align with "NCLEX MAP warning" in Hypertension, Hypotension, CO & SV? (Select all that apply)', '[{"id": "a", "text": "MAP 55 is acceptable organ perfusion."}, {"id": "b", "text": "Immediate BP support is prioritized."}, {"id": "c", "text": "No action needed unless MAP <20."}, {"id": "d", "text": "Oxygenation support is also prioritized."}, {"id": "e", "text": "MAP <60 is ischemia risk in note tip."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: MAP below 60 mmHg means organs are at risk of ischemia and immediate BP/oxygenation support is priority.', 'Hypertension Hypotension CO SV - NCLEX', true, 100, 1, true);
